// ==================== 唐诗管理器 ====================
import { CONFIG } from './config.js';

const PoemManager = {
    poems: [],
    poemIndex: {},
    currentIndex: 0,

    async init\(\) {
        try {
            const indexResponse = await fetch\(CONFIG.POEMS_INDEX_PATH\);
            const indexData = await indexResponse.json\(\);

            indexData.poems.forEach\(poemInfo => {
                this.poemIndex[poemInfo.id] = poemInfo;
            }\);

            const cachedPoems = localStorage.getItem\('tangpoem_poems_data'\);
            if \(cachedPoems\) {
                this.poems = JSON.parse\(cachedPoems\);
            } else {
                await this.loadAllPoems\(indexData.poems\);
            }
        } catch \(error\) {
            console.error\('加载唐诗数据失败:', error\);
            this.poems = [];
        }
    },

    async loadAllPoems\(poemsList\) {
        const loadedPoems = [];
        for \(const poemInfo of poemsList\) {
            try {
                const response = await fetch\(CONFIG.POEMS_DATA_PATH + poemInfo.file\);
                const poemData = await response.json\(\);
                loadedPoems.push\(poemData\);
            } catch \(error\) {
                console.error\('加载唐诗失败:', error\);
            }
        }
        this.poems = loadedPoems;
        localStorage.setItem\('tangpoem_poems_data', JSON.stringify\(this.poems\)\);
    },

    getAllPoems\(\) {
        return this.poems;
    },

    getPoemById\(id\) {
        return this.poems.find\(poem => poem.id === id\);
    },

    getCurrentPoem\(\) {
        return this.poems[this.currentIndex];
    },

    nextPoem\(\) {
        if \(this.currentIndex < this.poems.length - 1\) {
            this.currentIndex++;
            this.renderCurrentPoem\(\);
        }
    },

    prevPoem\(\) {
        if \(this.currentIndex > 0\) {
            this.currentIndex--;
            this.renderCurrentPoem\(\);
        }
    },

    renderCurrentPoem\(\) {
        const poem = this.getCurrentPoem\(\);
        if \(!poem\) return;

        document.getElementById\('poemTitle'\).textContent = poem.title;
        document.getElementById\('poemAuthor'\).textContent = poem.dynasty + ' · ' + poem.author;

        const contentEl = document.getElementById\('poemContent'\);
        contentEl.innerHTML = poem.content.map\(line => 
            '<div class="poem-line">' +
            '<div class="poem-text">' + line.text + '</div>' +
            '<div class="poem-pinyin">' + line.pinyin + '</div>' +
            '</div>'
        \).join\(''\);

        document.getElementById\('poemTranslation'\).innerHTML = 
            '<strong>译文：</strong>' + poem.translation;
    },

    initReciteMode\(\) {
        this.currentIndex = 0;
        this.renderCurrentPoem\(\);
    },

    getRandomPoems\(count\) {
        const shuffled = [...this.poems].sort\(\(\) => Math.random\(\) - 0.5\);
        return shuffled.slice\(0, Math.min\(count, shuffled.length\)\);
    },

    addPoem\(poemData\) {
        const newId = Math.max\(...this.poems.map\(p => p.id\), 0\) + 1;
        poemData.id = newId;
        this.poems.push\(poemData\);
        localStorage.setItem\('tangpoem_poems_data', JSON.stringify\(this.poems\)\);
        return newId;
    }
};

export { PoemManager };
EOFMARKER)
